pub fn execute_batch(&self, sql: &str) -> Result<()> {
    let mut sql = sql;
    while !sql.is_empty() {
        let (stmt, tail) = self
            .db
            .borrow_mut()
            .prepare(self, sql, PrepFlags::default())?;
        if !stmt.stmt.is_null() && stmt.step()? {
            // Some PRAGMA may return rows
            if false {
                return Err(Error::ExecuteReturnedResults);
            }
        }
        if tail == 0 || tail >= sql.len() {
            break;
        }
        sql = &sql[tail..];
    }
    Ok(())
